head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    if (dataList1.getCellData(rowIndex, "col2") == 1) {
        returnInfo = {
            id: "dynamic_select_" + rowIndex + "_" + colIndex,
            inputType: "select",
            options: {
                viewType: "icon"
            },
            itemSet: {
                nodeset: "data:dataList2",
                label: "col1",
                value: "col2"
            }
        };
    } else {
        returnInfo = {
            id: "dynamic_text_" + rowIndex + "_" + colIndex,
            inputType: "text",
            options: {}
        };
    }
    if (returnInfo) {
        console.log("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
};
scwin.grd_onviewchange = function(info) {
    grd1.refreshRow(info.rowIndex);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.trigger1_onclick = function(e) {
    var options = {
        type: "1",
        fileName: "test.xlsx"
    };
    grd1.advancedExcelDownload(options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a1",
        "col2": "1"
    }, {
        "col1": "a1",
        "col2": "2"
    }, {
        "col1": "a1",
        "col2": "a3"
    }];
    dataList1.setJSON(jsonData);
    dataList1.insertRow(0);
    dataList1.insertRow();
    window.jsonData2 = [{
        "col1": "a1_l",
        "col2": "a1"
    }, {
        "col1": "a2_l",
        "col2": "a2"
    }, {
        "col1": "a3_l",
        "col2": "a3"
    }];
    dataList2.setJSON(jsonData2);
    dataList1.setCellData(1, "col1", "a1");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
